import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {canonical,sha,occurrence,resolveIdentity,assignmentErrors,classifyProgramLifecycle,lifecycleTransition,extractReleaseOcr,lifecycleEventTypes,shapeErrors,validateProgramOccurrence,buildManifest,assertChecksum,assertSchema,normalizeEscortMobile,normalizeEmployeeMobile,reconcileEmployeeMobileRecords,extractEscortMessages,reconcileEscortIdentities,programWindowCandidates,priorAssignmentClosureReviews,releaseCandidate,verifiedMilestones,ghatDutyCandidates} from '../lib/employee-program-validation.mjs';
import {dryRun} from '../scripts/employee-program-dry-run.mjs';
const spec=JSON.parse(readFileSync(new URL('../docs/employee-program-mapping-v1.json',import.meta.url)));
const file='conversation-snapshot.json',selector='programs',shape=spec.sources[file].selectors[selector].shape;
const row={id:'synthetic',motherVessel:'Repeated vessel',lighterVessel:'Repeated lighter',escortName:'Same name',escortMobile:'01700000001',masterMobile:'01700000002',destination:'Port',startDate:'2026-01-01',endDate:'',shift:'D',status:'Recorded',source:'synthetic',notes:'',createdAt:'2026-01-01T00:00:00Z',revision:0,duplicateOf:null,details:{},aliases:['synthetic'],conflicts:[],evidence:[]};
const make=(r=row)=>({...occurrence(file,spec.sources[file].sha256,'/chunks/0/payload','/0',r,'a'.repeat(64)),domain:'program',selector});
const registry={employee:[{id:'e1',employee_id:'01700000001',status:'confirmed'},{id:'e2',employee_id:'01800000001',status:'confirmed'},{id:'a1',employee_id:'01900000001',status:'applicant'}],vessel:[{id:'v1'},{id:'v2'},{id:'v3'}],program:[{id:'p1'},{id:'p2'}]};
const approve=(targetId='e1',extra={})=>({kind:'employee',role:'employee',occurrenceId:make().id,targetId,decision:'APPROVED',approver:'reviewer',approvedOn:'2026-01-02',validFrom:'2025-01-01',validTo:null,evidenceSha:'b'.repeat(64),evidenceKind:'INDEPENDENT_AUTHORITY',...extra});
const resolve=a=>resolveIdentity(a,'employee',registry,'2026-01-01',make().id);
const validate=r=>validateProgramOccurrence(make(r),{shape,asOf:'2026-10-09'});
test('same name does not merge independently bound employees',()=>{assert.equal(resolve(approve()).id,'e1');assert.equal(resolve(approve('e2')).id,'e2');assert.equal(resolve(undefined).code,'IDENTITY_UNVERIFIED');});
test('EMP-002 supersedes same-phone separate-person operational identities',()=>{const rs=[{id:'s1',sourceOccurrenceId:'s1',employee_id:'01700000001',employee_name:'A',sourceRole:'employee_id',sourceRoleEstablished:true,reference:{occurrenceId:'s1'}},{id:'s2',sourceOccurrenceId:'s2',employee_id:'+8801700000001',employee_name:'B',sourceRole:'employee_id',sourceRoleEstablished:true,reference:{occurrenceId:'s2'}}];const r=reconcileEmployeeMobileRecords(rs);assert.equal(r.employees.length,1);assert.equal(r.employees[0].aliases.length,2);});
test('verified reference binding retains half-open periods; mobile identity is separate',()=>{assert.equal(resolve(approve('e1',{validTo:'2026-01-01'})).code,'IDENTITY_PERIOD_UNVERIFIED');assert.equal(resolve(approve('e2',{validFrom:'2026-01-01'})).id,'e2');});
test('applicant is not confirmed employee',()=>assert.equal(resolve(approve('a1')).code,'APPLICANT_NOT_EMPLOYEE'));
test('ambiguous labels and source identityVerified flag cannot approve',()=>assert.equal(resolve({identityVerified:true,name:'A',phone:'1'}).code,'IDENTITY_UNVERIFIED'));
test('payout and JID identity rejected without independent authority',()=>assert.equal(resolve(approve('e1',{evidenceKind:'WHATSAPP_JID'})).code,'IDENTITY_UNVERIFIED'));
test('approval cannot bind another source occurrence',()=>assert.equal(resolve(approve('e1',{occurrenceId:'wrong'})).code,'IDENTITY_UNVERIFIED'));
test('repeated vessel labels never merge program identities',()=>{const a=make(),b=make({...row,id:'another'});assert.notEqual(a.id,b.id);assert.ok(validate(row).reasons.includes('MOTHER_IDENTITY_UNVERIFIED'));});
test('multiple lighters and reuse over time supported',()=>{const events=[{id:'x1',programId:'p1',lighterId:'v2',employeeId:'e1',kind:'assigned',validFrom:'2026-01-01'},{id:'x2',programId:'p1',lighterId:'v3',employeeId:'e2',kind:'assigned',validFrom:'2026-01-01'},{id:'x3',programId:'p2',lighterId:'v2',employeeId:'e1',kind:'assigned',validFrom:'2026-02-01'}];assert.deepEqual(assignmentErrors(events,registry),[]);});
test('replacement and cancellation preserve chain',()=>{const events=[{id:'x1',programId:'p1',lighterId:'v2',employeeId:'e1',kind:'assigned',validFrom:'2026-01-01'},{id:'x2',programId:'p1',lighterId:'v2',employeeId:'e2',kind:'replaced',previousId:'x1',validFrom:'2026-01-02'},{id:'x3',programId:'p1',lighterId:'v2',employeeId:'e2',kind:'cancelled',previousId:'x2',validFrom:'2026-01-03'}];assert.deepEqual(assignmentErrors(events,registry),[]);assert.equal(events[0].employeeId,'e1');assert.ok(assignmentErrors([{...events[2],previousId:'absent'}],registry).includes('ASSIGNMENT_PREDECESSOR'));});
test('missing date and shift never invented',()=>{const r=validate({...row,startDate:'',shift:''});assert.ok(r.reasons.includes('MISSING_startDate'));assert.ok(r.reasons.includes('MISSING_shift'));});
test('conflicting projections remain unresolved',()=>assert.ok(validate({...row,conflicts:[{field:'motherVessel',existing:'A',incoming:'B',sourceRow:'r'}]}).reasons.includes('CONFLICTING_ASSERTIONS')));
test('duplicate source occurrence cannot create another candidate',()=>{const o=make(),r=buildManifest([o,o],{spec,asOf:'2026-10-09'});assert.equal(r.summary.duplicateOccurrenceRows,1);assert.equal(r.summary.eligible,0);});
test('source checksum mismatch fails closed',()=>assert.throws(()=>assertChecksum('changed','a'.repeat(64)),/SOURCE_CHECKSUM_MISMATCH/));
test('schema fingerprint mismatch fails closed',()=>assert.throws(()=>assertSchema({},'a'.repeat(64)),/SCHEMA_FINGERPRINT_MISMATCH/));
test('unknown keys including nested details are rejected and accounted for',()=>{const errors=shapeErrors({...row,unknown:'x',details:{unknown:'x'}},shape);assert.deepEqual(errors.filter(e=>e.code==='UNKNOWN_SOURCE_KEY').map(e=>e.path),['/details/unknown','/unknown']);});
test('missing foreign-key identity rejects approved binding',()=>assert.equal(resolve(approve('missing')).code,'MISSING_FOREIGN_KEY_IDENTITY'));
test('invalid calendar and reversed dates reject',()=>{assert.ok(validate({...row,startDate:'2026-02-30'}).reasons.includes('INVALID_startDate'));assert.ok(validate({...row,endDate:'2025-12-31'}).reasons.includes('DATE_ORDER'));});
test('dry-run manifest is deterministic and input order independent',()=>{const a=make(),b=make({...row,id:'b'}),options={spec,asOf:'2026-10-09'};assert.equal(canonical(buildManifest([a,b],options)),canonical(buildManifest([b,a],options)));});
test('different source versions cannot overwrite an occurrence',()=>assert.notEqual(make().id,occurrence(file,'c'.repeat(64),'/chunks/0/payload','/0',row,'a'.repeat(64)).id));
test('dry-run requires explicit catalog and as-of',()=>{assert.throws(()=>dryRun(),/EXPLICIT_AS_OF/);assert.throws(()=>dryRun({asOf:'2026-10-09'}),/LIVE_CATALOG_REQUIRED/);});
test('no production write or migration/import dependencies reachable',()=>{for(const f of ['lib/employee-program-validation.mjs','scripts/employee-program-dry-run.mjs']){const code=readFileSync(new URL('../'+f,import.meta.url),'utf8');assert.doesNotMatch(code,/createPool|database\.mjs|child_process|\.query\(|\bINSERT\b|\bUPDATE\b|\bDELETE\b|\bTRUNCATE\b|\bmigrate\(/);}});
test('no startup migration/import/preparation hook',()=>{const pkg=JSON.parse(readFileSync(new URL('../package.json',import.meta.url)));for(const k of ['start','dev','build','prestart','poststart'])assert.doesNotMatch(pkg.scripts[k]??'',/database\.mjs|employee-program|db:migrate|db:import/);assert.doesNotMatch(readFileSync(new URL('../lib/seed.ts',import.meta.url),'utf8'),/INSERT|migrate\(/);});
test('candidate is outside automatic migration discovery and append-only',()=>{const sql=readFileSync(new URL('../db/migration-candidates/0006_employee_program_identity.sql',import.meta.url),'utf8');assert.match(sql,/UNIQUE\(occurrence_id,role,event_key\)/);assert.match(sql,/FOREIGN KEY \(previous_id,program_id,lighter_id\)/);assert.match(sql,/BEFORE UPDATE OR DELETE/);assert.doesNotMatch(sql,/ALTER TABLE|DROP TABLE|CREATE DATABASE/);});
test('passive module imports perform no execution',()=>{const r=spawnSync(process.execPath,['--input-type=module','-e',"await import('./scripts/employee-program-dry-run.mjs')"],{cwd:new URL('../',import.meta.url),encoding:'utf8'});assert.equal(r.status,0);assert.equal(r.stdout,'');assert.equal(r.stderr,'');});

test('reviewed identities alone never imply assignment/business approval',()=>{const o=make(),r=validateProgramOccurrence(o,{shape,asOf:'2026-10-09',registry,approvals:[approve()]});assert.equal(r.bindings.employee,'+8801700000001');assert.ok(r.reasons.includes('ASSIGNMENT_EVIDENCE_NOT_SUPPLIED'));assert.ok(r.reasons.includes('BUSINESS_APPROVAL_NOT_SUPPLIED'));});

test('employee ambiguity reasons stay source-bound without merging',()=>{const a={...occurrence('accounts-snapshot.json',spec.sources['accounts-snapshot.json'].sha256,'/chunks/0/payload','/0',{name:'A',employeePhone:'1'}),domain:'employee',selector:'accountsCash'},b={...occurrence('accounts-snapshot.json',spec.sources['accounts-snapshot.json'].sha256,'/chunks/0/payload','/1',{name:'B',employeePhone:'1'}),domain:'employee',selector:'accountsCash'};const r=buildManifest([a,b],{spec,asOf:'2026-10-09'});assert.equal(r.rows.length,2);assert.ok(r.rows.every(x=>x.reasons.includes('SAME_EMPLOYEE_MOBILE_NAME_ALIASES')));assert.equal(r.summary.eligible,0);});
test('cross-version program assertion differences remain blocked',()=>{const a=make(),other='chat-archive.json',b={...occurrence(other,spec.sources[other].sha256,'/programs/0',null,{...row,motherVessel:'different'}),domain:'program',selector:'programs'};const r=buildManifest([a,b],{spec,asOf:'2026-10-09'});assert.ok(r.rows.every(x=>x.reasons.includes('CROSS_VERSION_ASSERTION_CONFLICT')));assert.equal(r.summary.blocked,2);});

const ref=id=>({occurrenceId:id,sourceExportSha:'a'.repeat(64),evidenceHref:'/private/archive.json',nativeHref:null});
const message=(id='msg1',day='2026-01-01',extra={})=>({id,chatKey:'office',sender:'Admin label',messageDate:day,time:'12:00',body:'Mother Vessel: MV Mother\nLighter Vessel: MV Lighter\nMaster Mobile: 01700000009\nEscort Name: First Name\nEscort Mobile: 01700000001\nDuty Start Date: 01.01.2026 (D)',mediaNames:[],reference:ref(id),...extra});
const roleProof=(role='admin',extra={})=>({role,chatKey:'office',sender:'Admin label',sourceExportSha:'a'.repeat(64),decision:'APPROVED',evidenceKind:'OWNER_VERIFIED_MESSAGE_ROLE',approver:'owner',approvedOn:'2026-01-01',validFrom:'2025-01-01',validTo:null,evidenceSha:'b'.repeat(64),...extra});
const extract=(ms,bindings=[roleProof()])=>extractEscortMessages(ms,{roleBindings:bindings,asOf:'2026-10-09'});
test('explicit Escort Mobile normalization supports BD formats and Bengali digits',()=>{assert.equal(normalizeEscortMobile('০১৭০০-০০০০০১'),'+8801700000001');assert.equal(normalizeEscortMobile('+880 1700 000001'),'+8801700000001');assert.equal(normalizeEscortMobile('01700000001 / 01800000001'),null);assert.equal(normalizeEscortMobile('1700000001@s.whatsapp.net'),null);});
test('sender/master/payout/JID roles never become Escort Mobile',()=>{for(const role of ['sender','masterMobile','payoutPhone','jid','lid','employeePhone'])assert.equal(normalizeEscortMobile('01700000001',role),null);const e=extract([message('m','2026-01-01',{body:'Escort Name: A\nMaster Mobile: 01700000001\nStart Date: 01.01.2026 (D)'})])[0];assert.equal(e.escortKey,null);assert.notEqual(e.classification,'ADMIN_CONFIRMATION_CANDIDATE');});
test('same explicit Escort Mobile and different names preserve aliases together',()=>{const es=extract([message(),message('msg2','2026-01-02',{body:message().body.replace('First Name','Second Name')})]);const r=reconcileEscortIdentities(es);assert.equal(r.identities.length,1);assert.deepEqual(r.identities[0].aliases,['First Name','Second Name']);assert.equal(r.identities[0].employmentStatus,'NOT_INFERRED');assert.ok(r.identities[0].references.length===2);});
test('same name different Escort Mobile remains separate',()=>{const r=reconcileEscortIdentities(extract([message(),message('msg2','2026-01-02',{body:message().body.replace('01700000001','01800000001')})]));assert.equal(r.identities.length,2);assert.notEqual(r.identities[0].internalId,r.identities[1].internalId);assert.equal(r.sameNameMultipleMobileGroups,1);});
test('existing immutable identity retained and independently linked phones can match it',()=>{const es=extract([message(),message('msg2','2026-01-02',{body:message().body.replace('01700000001','01800000001')})]);const r=reconcileEscortIdentities(es,{knownIdentities:[{id:'immutable-internal-id',employee_id:'01700000001',contacts:[{escortKey:'+8801700000001',verified:true,fieldRole:'escortMobile'},{escortKey:'+8801800000001',verified:true,fieldRole:'escortMobile'}]}],ownerApprovedLinks:[{fromEmployeeId:'01800000001',targetInternalId:'immutable-internal-id',decision:'APPROVED',approver:'owner',approvedOn:'2026-10-09',evidenceSha:'b'.repeat(64)}]});assert.ok(r.identities.every(i=>i.internalId==='immutable-internal-id'));assert.ok(r.identities.every(i=>i.contactHistory.every(c=>c.validFrom===null&&c.validTo===null)));});
test('EMP-002 retains same operational mobile identity while preserving ownership warning',()=>{const r=reconcileEscortIdentities(extract([message()]),{ownershipContradictions:[{escortKey:'+8801700000001',verified:true}]});assert.equal(r.identities.length,1);assert.equal(r.identities[0].identityState,'OPERATIONAL_EMPLOYEE_CANDIDATE');assert.ok(r.identities[0].internalId);assert.deepEqual(r.identities[0].aliases,['First Name']);assert.equal(r.identities[0].ownershipWarnings.length,1);});
test('repeated conflicting Escort Mobile fields stay review',()=>{const es=extract([message('m','2026-01-01',{body:message().body+'\nEscort Mobile: 01800000001'})]);assert.equal(es[0].classification,'REVIEW');assert.equal(reconcileEscortIdentities(es).identities.length,0);});
test('Admin confirmation needs all six fields; destination optional',()=>{const e=extract([message()])[0];assert.equal(e.classification,'ADMIN_CONFIRMATION_CANDIDATE');assert.equal(e.complete,true);assert.deepEqual(e.missing,[]);assert.ok(!e.rawFields.destination);assert.equal(e.startDate,'2026-01-01');assert.equal(e.shift,'D');});
test('unverified sender alias and wrong source/chat role cannot confirm',()=>{assert.equal(extract([message()],[])[0].classification,'REVIEW');assert.equal(extract([message()],[roleProof('admin',{chatKey:'different'})])[0].classification,'REVIEW');assert.equal(extract([message()],[roleProof('admin',{sourceExportSha:'c'.repeat(64)})])[0].classification,'REVIEW');});
test('client service order is Draft; incomplete Admin confirmation is Review',()=>{assert.equal(extract([message()],[roleProof('client')])[0].classification,'DRAFT');const e=extract([message('m','2026-01-01',{body:message().body.replace(/\nDuty Start Date:.*/, '')})])[0];assert.equal(e.classification,'REVIEW');assert.ok(e.missing.includes('startDate'));assert.ok(e.missing.includes('shift'));});
test('exact same-day confirmation creates duplicate candidate with both references',()=>{const pairs=programWindowCandidates(extract([message(),message('m2')]));assert.equal(pairs.length,1);assert.ok(pairs[0].reasons.includes('SAME_DAY_DUPLICATE_CANDIDATE'));assert.equal(pairs[0].references.length,2);assert.equal(pairs[0].automaticCancel,false);});
test('three-day duplicate boundary includes day three, excludes day four',()=>{const three=programWindowCandidates(extract([message(),message('m2','2026-01-04')]));assert.ok(three[0].reasons.includes('THREE_DAY_DUPLICATE_CANDIDATE'));const four=programWindowCandidates(extract([message(),message('m2','2026-01-05')]));assert.ok(!four[0].reasons.includes('THREE_DAY_DUPLICATE_CANDIDATE'));assert.ok(four[0].reasons.includes('FIVE_DAY_CANCEL_RESTART_REPLACEMENT_REVIEW'));});
test('changed duty shift or master number within three days requires correction review',()=>{for(const [before,after] of [['(D)','(N)'],['01700000009','01800000009']]){const pairs=programWindowCandidates(extract([message(),message('m2','2026-01-03',{body:message().body.replace(before,after)})]));assert.ok(pairs[0].reasons.includes('THREE_DAY_CORRECTION_REVIEW'));assert.ok(!pairs[0].reasons.includes('SAME_DAY_DUPLICATE_CANDIDATE'));}});
test('repeated lighter within five days reviews cancellation/restart/replacement, never cancels',()=>{const five=programWindowCandidates(extract([message(),message('m2','2026-01-06',{body:message().body.replace('01700000001','01800000001')})]));assert.ok(five[0].reasons.includes('FIVE_DAY_CANCEL_RESTART_REPLACEMENT_REVIEW'));assert.equal(five[0].automaticCancel,false);assert.deepEqual(programWindowCandidates(extract([message(),message('m2','2026-01-07')])),[]);});
test('one mother supports fifty lighter programs without duplicate by mother alone',()=>{const es=extract(Array.from({length:50},(_,i)=>message('m'+i,'2026-01-01',{body:message().body.replace('MV Lighter','MV Lighter '+i)})));assert.equal(es.length,50);assert.equal(new Set(es.map(e=>e.businessKey)).size,50);assert.deepEqual(programWindowCandidates(es),[]);});
test('new verified assignment reviews prior open assignment without closing it',()=>{const es=extract([message(),message('m2','2026-01-03',{body:message().body.replace('MV Lighter','MV Different')})]);const r=priorAssignmentClosureReviews(es);assert.equal(r.length,1);assert.equal(r[0].automaticClosure,false);assert.equal(r[0].releaseDate,null);assert.equal(r[0].dutyTotal,null);assert.deepEqual(priorAssignmentClosureReviews(extract([message(),message('m2')],[])),[]);});
test('Release media references survive missing OCR and no completion is fabricated',()=>{const r=releaseCandidate(message('r','2026-01-01',{body:'Release Slip image',mediaNames:['original.jpg']}));assert.equal(r.classification,'RELEASE_REVIEW');assert.deepEqual(r.mediaReferences,['original.jpg']);assert.ok(r.reasons.includes('OCR_MEDIA_UNAVAILABLE'));assert.equal(r.releaseDate,null);assert.equal(r.programCompleted,false);assert.equal(r.dutyTotal,null);});
test('available release image requires OCR; reviewed identity and release fields may classify Released only',()=>{const m=message('r','2026-01-01',{body:'Release Slip',mediaNames:['original.jpg']});assert.ok(releaseCandidate(m,{mediaAvailable:true}).reasons.includes('OCR_REQUIRED'));const ocr={mediaSha:'a'.repeat(64),reference:'original.jpg',fields:{motherVessel:'M',lighterVessel:'L',escortMobile:'01700000001',releaseDate:'2026-01-03'}};const verification={decision:'APPROVED',approver:'owner',mediaSha:ocr.mediaSha,programId:'p',identityFieldsVerified:true,releaseFieldsVerified:true};const r=releaseCandidate(m,{mediaAvailable:true,ocrEvidence:ocr,verification});assert.equal(r.classification,'RELEASED_CANDIDATE');assert.equal(r.releaseDate,'2026-01-03');assert.equal(r.programCompleted,false);assert.equal(r.settlementApproved,false);assert.equal(r.paymentCompleted,false);assert.equal(releaseCandidate(m,{mediaAvailable:false,ocrEvidence:ocr,verification}).classification,'RELEASE_REVIEW');});
test('Released, Program Completed, Settlement Approved and Payment Completed are distinct',()=>{assert.deepEqual(verifiedMilestones({release:true}),{release:'Released',program:'Not verified',settlement:'Not verified',payment:'Not verified'});assert.equal(verifiedMilestones({settlement:true}).payment,'Not verified');});
const payment=(id,date,extra={})=>({id,date,employeePhone:'01700000001',amountCents:20000,reference:{occurrenceId:id,message:ref(id)},...extra});
test('three consecutive BDT200 instruction days create high-priority Ghat review only',()=>{const r=ghatDutyCandidates([payment('a','2026-01-01'),payment('b','2026-01-02'),payment('c','2026-01-03')],{currencyContext:'BDT'});assert.equal(r.candidates.length,1);assert.equal(r.candidates[0].classification,'HIGH_PRIORITY_GHAT_REVIEW');assert.equal(r.candidates[0].instructionCount,3);assert.equal(r.candidates[0].verifiedTransferCount,0);assert.equal(r.candidates[0].cashPosting,false);assert.equal(r.candidates[0].attendancePosting,false);assert.equal(r.candidates[0].payrollPosting,false);assert.equal(r.candidates[0].settlementPosting,false);});
test('Ghat days are distinct, same-day repeats and gaps cannot fake consecutive days',()=>{const r=ghatDutyCandidates([payment('a','2026-01-01'),payment('a','2026-01-01'),payment('b','2026-01-01'),payment('c','2026-01-03')],{currencyContext:'BDT'});assert.equal(r.candidates[0].classification,'POSSIBLE_GHAT_DUTY');assert.equal(r.excluded.filter(e=>e.reason==='DUPLICATE_PAYMENT_EVIDENCE').length,1);assert.deepEqual(r.candidates[0].consecutiveRuns,[]);});
test('Ghat requires BDT context and exact minor-unit amount, never payment status alone',()=>{assert.equal(ghatDutyCandidates([payment('a','2026-01-01')]).evidence.length,0);assert.equal(ghatDutyCandidates([payment('a','2026-01-01',{amountCents:200})],{currencyContext:'BDT'}).evidence.length,0);const r=ghatDutyCandidates([payment('a','2026-01-01',{status:'Paid'})],{currencyContext:'BDT'});assert.equal(r.evidence[0].evidenceType,'PAYMENT_INSTRUCTION');assert.equal(r.evidence[0].personIdentityResolved,true);});
test('independent transfer proof is distinct from instruction and remains no posting',()=>{const p=payment('a','2026-01-01',{transferVerification:{decision:'APPROVED',approver:'owner',approvedOn:'2026-01-03',paymentEvidenceId:'a',paymentDate:'2026-01-01',amountCents:20000,currency:'BDT',receiptSha:'a'.repeat(64),transferReference:'receipt-1'}});assert.equal(ghatDutyCandidates([p],{currencyContext:'BDT'}).evidence[0].evidenceType,'VERIFIED_TRANSFER');});
test('owner reconciliation is deterministic across message/payment input order',()=>{const ms=[message(),message('m2','2026-01-03')];assert.equal(canonical(extract(ms)),canonical(extract([...ms].reverse())));const ps=[payment('a','2026-01-01'),payment('b','2026-01-02'),payment('c','2026-01-03')];assert.equal(canonical(ghatDutyCandidates(ps,{currencyContext:'BDT'})),canonical(ghatDutyCandidates([...ps].reverse(),{currencyContext:'BDT'})));});
test('Client order followed by Admin confirmation references the same program instead of duplicate creation',()=>{const client=message('order','2026-01-01',{sender:'Client label'}),admin=message('confirm','2026-01-02');const es=extract([client,admin],[roleProof('client',{sender:'Client label'}),roleProof()]);assert.equal(es.filter(e=>e.classification==='DRAFT').length,1);assert.equal(es.filter(e=>e.classification==='ADMIN_CONFIRMATION_CANDIDATE').length,1);const p=programWindowCandidates(es)[0];assert.ok(p.reasons.includes('ORDER_CONFIRMATION_REFERENCE'));assert.ok(!p.reasons.includes('THREE_DAY_DUPLICATE_CANDIDATE'));});
const ledgerRecord=(id,mobile,name='Original Name',extra={})=>({id,sourceOccurrenceId:id,employee_id:mobile,employee_name:name,sourceRole:'employee_id',sourceRoleEstablished:true,reference:{occurrenceId:id,originalMessage:'wa-'+id,evidenceHref:'/private/source.json',sourceLine:5},...extra});
test('EMP-001 mobile-valued employee_id is accepted without UUID or Escort Mobile',()=>{const r=reconcileEmployeeMobileRecords([ledgerRecord('l1','01700000001')]);assert.equal(r.employees[0].employee_id,'+8801700000001');assert.equal(r.employees.length,1);assert.equal(r.unresolved.length,0);assert.ok(!Object.hasOwn(r.employees[0],'escort_mobile'));});
test('EMP-003 Bengali and English names are aliases, with original references retained',()=>{const rs=[ledgerRecord('l1','01800000001','Md Hridoy'),ledgerRecord('l2','+8801800000001','মোঃ হৃদয়'),ledgerRecord('l3','01800000001','Hridoy Islam')];const r=reconcileEmployeeMobileRecords(rs);assert.equal(r.employees.length,1);assert.deepEqual(new Set(r.employees[0].aliases.map(a=>a.name)),new Set(rs.map(r=>r.employee_name)));assert.equal(r.employees[0].sourceReferences.length,3);for(const a of r.employees[0].aliases)assert.ok(a.sourceReferences[0].originalMessage);assert.equal(rs[0].employee_name,'Md Hridoy');});
test('EMP-004 optional escort_mobile matches the existing ledger employee',()=>{const known=[{id:'retained-internal-key',employee_id:'01800000001'}],r=reconcileEmployeeMobileRecords([ledgerRecord('l1','+8801800000001','Alias',{sourceRole:'escort_mobile'})],{knownEmployees:known});assert.equal(r.employees.length,1);assert.equal(r.employees[0].internalId,'retained-internal-key');assert.equal(r.employees[0].identityState,'MATCHED_EXISTING_IDENTITY');});
test('EMP-005 same name and different mobiles stay separate without an owner-approved link',()=>{const r=reconcileEmployeeMobileRecords([ledgerRecord('l1','01700000001','Same'),ledgerRecord('l2','01800000001','Same')]);assert.equal(r.employees.length,2);assert.equal(r.summary.sameNameDifferentMobileGroups,1);assert.notEqual(r.employees[0].internalId,r.employees[1].internalId);});
test('EMP missing mobile does not generate an employee or fabricated ID',()=>{const r=reconcileEmployeeMobileRecords([ledgerRecord('l1','')]);assert.equal(r.employees.length,0);assert.equal(r.unresolved[0].reason,'EMPLOYEE_MOBILE_MISSING');assert.equal(r.unresolved[0].employee_id,null);assert.equal(r.unresolved[0].internalId,null);});
test('EMP invalid or ambiguous mobile is Review; digits are never guessed',()=>{for(const value of ['018XXXXXXXX','01700000001/01800000001','1700000001@lid','12345',12345]){const r=reconcileEmployeeMobileRecords([ledgerRecord('l1',value)]);assert.equal(r.employees.length,0);assert.ok(r.unresolved.length===1);}});
test('EMP normalization preserves original source value and formats match one mobile',()=>{const r=reconcileEmployeeMobileRecords([ledgerRecord('l1','০১৭০০-০০০০০১'),ledgerRecord('l2','+880 1700 000001'),ledgerRecord('l3','01700000001')]);assert.equal(r.employees.length,1);assert.deepEqual(r.employees[0].contactHistory.map(c=>c.originalValue),['০১৭০০-০০০০০১','+880 1700 000001','01700000001']);});
test('EMP-006 sender/master/client/payout/JID/LID roles are excluded even with matching digits',()=>{for(const role of ['sender','masterMobile','client','payoutPhone','jid','lid']){assert.equal(normalizeEmployeeMobile('01700000001',role),null);assert.equal(reconcileEmployeeMobileRecords([ledgerRecord('l1','01700000001','A',{sourceRole:role})]).employees.length,0);}assert.equal(reconcileEmployeeMobileRecords([ledgerRecord('l1','01700000001','A',{sourceRoleEstablished:false})]).unresolved[0].reason,'EMPLOYEE_SOURCE_ROLE_UNESTABLISHED');});
test('EMP repeated processing yields no duplicate employee, alias or reference records',()=>{const rs=[ledgerRecord('l1','01700000001','Name'),ledgerRecord('l2','+8801700000001','Name')];const once=reconcileEmployeeMobileRecords(rs),twice=reconcileEmployeeMobileRecords([...rs,...rs].reverse());assert.equal(canonical(once),canonical(twice));assert.equal(twice.employees.length,1);assert.equal(twice.employees[0].aliases.length,1);assert.equal(twice.employees[0].aliases[0].sourceReferences.length,2);});
test('EMP alias ID remains deterministic when additional evidence is appended',()=>{const rs=[ledgerRecord('l1','01700000001','Name')],a=reconcileEmployeeMobileRecords(rs),b=reconcileEmployeeMobileRecords([...rs,ledgerRecord('l2','01700000001','Other')]);assert.equal(a.employees[0].internalId,b.employees[0].internalId);assert.equal(a.employees[0].aliases[0].id,b.employees[0].aliases.find(x=>x.name==='Name').id);});
test('EMP owner-approved link preserves internal identity; absent/mismatched proof cannot link',()=>{const known=[{id:'internal',employee_id:'01700000001'}],rs=[ledgerRecord('l1','01800000001')];assert.notEqual(reconcileEmployeeMobileRecords(rs,{knownEmployees:known}).employees[0].internalId,'internal');const link={fromEmployeeId:'01800000001',targetInternalId:'internal',decision:'APPROVED',approver:'owner',approvedOn:'2026-10-09',evidenceSha:'a'.repeat(64)};assert.equal(reconcileEmployeeMobileRecords(rs,{knownEmployees:known,ownerApprovedLinks:[link]}).employees[0].internalId,'internal');assert.notEqual(reconcileEmployeeMobileRecords(rs,{knownEmployees:known,ownerApprovedLinks:[{...link,decision:'PENDING'}]}).employees[0].internalId,'internal');});
test('EMP optional employee_id/escort_mobile disagreement stays Review without a second employee',()=>{const r=reconcileEmployeeMobileRecords([ledgerRecord('l1','01700000001','Name',{escort_mobile:'01800000001'})]);assert.equal(r.employees.length,0);assert.equal(r.unresolved[0].reason,'EMPLOYEE_ESCORT_MOBILE_MISMATCH_REVIEW');});
test('EMP source occurrence conflict fails closed instead of overwriting alias lineage',()=>assert.throws(()=>reconcileEmployeeMobileRecords([ledgerRecord('l1','01700000001','A'),ledgerRecord('l1','01700000001','B')]),/EMPLOYEE_SOURCE_OCCURRENCE_CONFLICT/));
test('Program confirmation can reuse labeled Employee ID; separate Escort Mobile is not mandatory',()=>{const e=extract([message('ledger-role','2026-01-01',{body:message().body.replace('Escort Mobile:','Employee ID:')})])[0];assert.equal(e.classification,'ADMIN_CONFIRMATION_CANDIDATE');assert.equal(e.escortKey,'+8801700000001');assert.equal(e.rawFields.escortMobile,undefined);assert.equal(reconcileEscortIdentities([e]).identities.length,1);});
test('SQL candidate keeps eleven tables and distinguishes operational mobile from technical id',()=>{const sql=readFileSync(new URL('../db/migration-candidates/0006_employee_program_identity.sql',import.meta.url),'utf8');assert.equal((sql.match(/CREATE TABLE /g)??[]).length,11);assert.match(sql,/employee_id text NOT NULL UNIQUE/);assert.match(sql,/REFERENCES ep_employees\(employee_id\)/);assert.doesNotMatch(sql,/escort_mobile text|ALTER TABLE|CREATE DATABASE/);});
test('EMP verified immutable-ID binding returns the operational mobile separately, never replaces employee_id',()=>{const result=resolve(approve('e1',{evidenceKind:'OWNER_VERIFIED_EMPLOYEE_MOBILE',fieldRole:'employee_id',fieldRoleVerified:true,sourceEmployeeId:'01700000001'}));assert.equal(result.id,'e1');assert.equal(result.employee_id,'+8801700000001');assert.equal(resolve(approve('e1',{evidenceKind:'OWNER_VERIFIED_EMPLOYEE_MOBILE',fieldRole:'payoutPhone',fieldRoleVerified:true,sourceEmployeeId:'01700000001'})).code,'IDENTITY_UNVERIFIED');});

test('owner register pins all current mobile rules and preserves superseded history',()=>{const bytes=readFileSync(new URL('../'+spec.ownerRuleRegister.path,import.meta.url));assertChecksum(bytes,spec.ownerRuleRegister.sha256);const r=JSON.parse(bytes);assert.equal(r.version,spec.version);assert.equal(r.productionExecutionAuthorized,false);assert.equal(r.rules.filter(x=>x.status==='ACTIVE'&&x.id.startsWith('EMP-')).length,6);assert.equal(r.history.filter(x=>x.status==='SUPERSEDED').length,2);});
test('assignment operational employee_id uses mobile rather than internal relational id',()=>{const e={id:'mobile-event',employee_id:'+8801700000001',programId:'p1',lighterId:'v1',kind:'assigned',validFrom:'2026-01-01',validTo:null};assert.deepEqual(assignmentErrors([e],registry),[]);assert.ok(assignmentErrors([{...e,employee_id:'e1'}],registry).includes('MISSING_FOREIGN_KEY_IDENTITY'));});

const life=(messages,options={})=>classifyProgramLifecycle(messages,{asOf:'2026-10-09',roleBindings:[roleProof(),roleProof('client',{sender:'Client'}),roleProof('requester',{sender:'Requester'})],...options});
const programContext=(extra={})=>({id:'p',state:'active',motherVessel:'MV Mother',lighterVessel:'MV Lighter',employee_id:'01700000001',startDate:'2026-01-01',shift:'D',messageDate:'2026-01-01',lastMessageDate:'2026-01-01',reference:ref('known'),verification:{decision:'APPROVED',approver:'owner',approvedOn:'2026-01-01',evidenceSha:'b'.repeat(64)},...extra});
const transitionMessage=(id,type,date='2026-01-02',fields='')=>message(id,date,{body:type+'\nProgram ID: p\nEffective Date: '+date+(fields?'\n'+fields:'')});
const transitionProof=(id,extra={})=>({decision:'APPROVED',approver:'owner',approvedOn:'2026-01-05',evidenceSha:'b'.repeat(64),programId:'p',occurrenceId:id,...extra});
test('lifecycle: fifty different lighters under one mother create fifty candidate programs',()=>{const r=life(Array.from({length:50},(_,i)=>message('l'+i,'2026-01-01',{body:message().body.replace('MV Lighter','MV Lighter '+i)})));assert.equal(r.programs.length,50);assert.ok(r.programs.every(p=>p.state==='confirmed'&&p.actualStartDate===null));assert.equal(r.summary.verifiedOperationalPrograms,0);});
test('lifecycle: repeated same-day and within-three-day confirmation retains one program and all references',()=>{const r=life([message('a'),message('b'),message('c','2026-01-04')]);assert.equal(r.programs.length,1);assert.equal(r.programs[0].references.length,3);assert.equal(r.events.filter(e=>e.eventType==='PROGRAM_DUPLICATE').length,2);});
test('lifecycle: repeated lighter on day five reviews instead of silently creating or cancelling',()=>{const r=life([message('a'),message('b','2026-01-06')]);assert.equal(r.programs.length,1);assert.equal(r.events.find(e=>e.messageId==='b').classification,'FIVE_DAY_RECURRENCE_REVIEW');assert.equal(r.programs[0].state,'confirmed');});
test('lifecycle: same lighter beyond five days may create a new candidate and closure review',()=>{const r=life([message('a'),message('b','2026-01-07',{body:message().body.replace('01.01.2026','07.01.2026')})]);assert.equal(r.programs.length,2);const e=r.events.find(e=>e.messageId==='b');assert.ok(e.reasons.includes('AFTER_FIVE_DAYS_NEW_PROGRAM_CANDIDATE'));assert.ok(e.reasons.some(r=>r.startsWith('PRIOR_ASSIGNMENT_CLOSURE_REVIEW:')));assert.ok(r.assignments.every(a=>a.open));assert.ok(r.programs.every(p=>p.endDate===null));});
test('lifecycle: same name different mobile is not alias; within five days requires replacement evidence',()=>{const r=life([message('a'),message('b','2026-01-02',{body:message().body.replace('01700000001','01800000001')})]);assert.equal(r.programs.length,1);assert.equal(r.events.find(e=>e.messageId==='b').accepted,false);assert.equal(reconcileEscortIdentities(extract([message('a'),message('b','2026-01-02',{body:message().body.replace('01700000001','01800000001')})])).identities.length,2);});
test('lifecycle: same mobile name alias confirmation adds evidence without a second program',()=>{const r=life([message('a'),message('b','2026-01-02',{body:message().body.replace('First Name','মোঃ প্রথম')})]);assert.equal(r.programs.length,1);assert.equal(r.events.find(e=>e.messageId==='b').eventType,'PROGRAM_DUPLICATE');assert.equal(r.events.find(e=>e.messageId==='b').rawFields.escortName,'মোঃ প্রথম');});
test('lifecycle: incomplete client Draft retains original body and missing fields',()=>{const m=message('draft','2026-01-01',{sender:'Client',body:'Client Escort Service Order:\nMother Vessel: MV Mother'}),r=life([m]);assert.equal(r.orders.length,1);assert.equal(r.programs.length,0);assert.equal(r.events[0].classification,'ORDER_DRAFT');assert.equal(r.events[0].originalMessage,m.body);assert.ok(r.events[0].missing.includes('employeeMobile'));assert.deepEqual(r.orders[0].references,[m.reference]);});
test('lifecycle: repeated equivalent incomplete Draft links evidence to same business order',()=>{const a=message('d1','2026-01-01',{sender:'Client',body:'Client Escort Service Order:\nMother Vessel: MV Mother'}),b=message('d2','2026-01-02',{...a,id:'d2',messageDate:'2026-01-02',reference:ref('d2')});const r=life([a,b]);assert.equal(r.orders.length,1);assert.equal(r.orders[0].references.length,2);});
test('lifecycle: complete Admin links and promotes incomplete Draft while preserving client reference',()=>{const d=message('draft','2026-01-01',{sender:'Client',body:'Client Escort Service Order:\nMother Vessel: MV Mother'}),a=message('admin','2026-01-02'),r=life([d,a]);assert.equal(r.orders[0].state,'confirmed');assert.equal(r.programs.length,1);assert.equal(r.events.find(e=>e.messageId==='admin').linkedOrderId,r.orders[0].id);assert.deepEqual(new Set(r.programs[0].references.map(x=>x.occurrenceId)),new Set(['draft','admin']));});
test('lifecycle: complete fields do not authenticate an unverified Admin sender',()=>{const r=life([message()],{roleBindings:[]});assert.equal(r.programs.length,0);assert.equal(r.events[0].classification,'REVIEW_REQUIRED');assert.equal(r.events[0].roleEvidence,null);assert.ok(r.events[0].reasons.includes('ADMIN_ROLE_UNVERIFIED'));});
test('lifecycle: unmatched verified Admin candidate does not fabricate a client order',()=>{const r=life([message()]);assert.equal(r.programs.length,1);assert.equal(r.orders.length,0);assert.equal(r.events[0].linkedOrderId,null);assert.ok(r.events[0].reasons.includes('UNMATCHED_ADMIN_CONFIRMATION'));assert.equal(r.events[0].classification,'CONFIRMED_PROGRAM_CANDIDATE');});
test('lifecycle: authorized requester can submit Draft but cannot confirm',()=>{const r=life([message('r','2026-01-01',{sender:'Requester',body:'Escort Service Order:\n'+message().body})]);assert.equal(r.orders.length,1);assert.equal(r.programs.length,0);});
test('lifecycle: cancellation then source-bound restart keeps prior program and assignment history',()=>{const c=transitionMessage('cancel','Program cancelled'),restart=message('restart','2026-01-03',{body:'Program restart\nProgram ID: p\nEffective Date: 2026-01-03\n'+message().body.replace('01.01.2026','03.01.2026')}),r=life([c,restart],{knownPrograms:[programContext()],transitionEvidence:{restart:transitionProof('restart')}});assert.equal(r.programs.length,1);assert.equal(r.programs[0].state,'confirmed');assert.equal(r.programs[0].history.length,2);assert.equal(r.assignments.length,2);const prior=r.assignments.find(a=>a.closedBy);assert.equal(prior.endDate,'2026-01-02');assert.equal(r.assignments.find(a=>a.open).predecessorId,prior.id);});
test('lifecycle: missing cancellation date keeps old state intact',()=>{const r=life([message('c','2026-01-02',{body:'Program cancelled\nProgram ID: p'})],{knownPrograms:[programContext()]});assert.equal(r.programs[0].state,'active');assert.ok(r.events[0].reasons.includes('EFFECTIVE_DATE_UNVERIFIED'));});
test('lifecycle: escort replacement preserves old/new mobiles and predecessor/successor',()=>{const m=transitionMessage('replace','Escort replacement','2026-01-02','Old Employee ID: 01700000001\nNew Employee ID: 01800000001'),r=life([m],{knownPrograms:[programContext()]});assert.equal(r.events[0].accepted,true);assert.equal(r.programs[0].employee_id,'+8801800000001');assert.equal(r.assignments.length,2);const prior=r.assignments.find(a=>!a.open),next=r.assignments.find(a=>a.open);assert.equal(prior.employee_id,'+8801700000001');assert.equal(next.predecessorId,prior.id);assert.equal(prior.successorId,next.id);});
test('lifecycle: shift missing blocks confirmation; message date remains separate from duty date',()=>{const m=message('s','2026-01-05',{body:message().body.replace(' (D)','')}),r=life([m]);assert.equal(r.programs.length,0);assert.ok(r.events[0].missing.includes('shift'));assert.equal(r.events[0].messageTimestamp,'2026-01-05T12:00');assert.equal(r.events[0].startDate,'2026-01-01');});
test('lifecycle: actual Duty Start requires explicit evidence and does not equal confirmation',()=>{const r=life([transitionMessage('start','Duty started','2026-01-02','Actual Start Date: 2026-01-02')],{knownPrograms:[programContext({state:'confirmed'})]});assert.equal(r.programs[0].state,'active');assert.equal(r.programs[0].plannedStartDate,'2026-01-01');assert.equal(r.programs[0].startDate,'2026-01-01');assert.equal(r.programs[0].actualStartDate,'2026-01-02');const bad=life([transitionMessage('bad','Duty started')],{knownPrograms:[programContext({state:'confirmed'})]});assert.equal(bad.programs[0].state,'confirmed');});
test('release: missing vessel names can propose a unique mobile/chronology program; never fabricate fields',()=>{const m=message('r','2026-01-03',{body:'Release Slip',mediaNames:['original.jpg']}),ocr={mediaSha:'a'.repeat(64),reference:'original.jpg',fields:{employee_id:'01700000001',releaseDate:'2026-01-03'}},verification={decision:'APPROVED',approver:'owner',mediaSha:ocr.mediaSha,programId:'p',identityFieldsVerified:true,releaseFieldsVerified:true};const r=releaseCandidate(m,{mediaAvailable:true,ocrEvidence:ocr,verification,programs:[programContext()]});assert.equal(r.classification,'RELEASED_CANDIDATE');assert.deepEqual(r.proposedProgramIds,['p']);assert.equal(r.ocrEvidence.fields.motherVessel,undefined);});
test('release: OCR ambiguity and multiple matching programs stay review',()=>{const m=message('r','2026-01-03',{body:'Release Slip'}),ocr={mediaSha:'a'.repeat(64),reference:'doc',fields:{employee_id:'01700000001',releaseDate:'2026-01-03'},ambiguities:['release date uncertain']};const r=releaseCandidate(m,{mediaAvailable:true,ocrEvidence:ocr,programs:[programContext(),programContext({id:'q'})]});assert.equal(r.classification,'RELEASE_REVIEW');assert.ok(r.reasons.includes('OCR_AMBIGUITY_REVIEW'));assert.ok(r.reasons.includes('RELEASE_PROGRAM_MATCH_AMBIGUOUS'));assert.equal(r.releaseDate,null);});
test('release: injected offline OCR hashes exact media and remains unapproved evidence',()=>{const bytes=new Uint8Array([1,2,3]),r=extractReleaseOcr({mediaBytes:bytes,reference:ref('image'),extractor:()=>({fields:{employee_id:'01700000001'},rawText:'original text',ambiguities:['date missing'],extractor:'isolated synthetic'})});assert.equal(r.mediaSha,sha(bytes));assert.equal(r.approval,false);assert.deepEqual(r.ambiguities,['date missing']);assert.throws(()=>extractReleaseOcr({reference:ref('image')}),/OCR_SOURCE_MEDIA_REQUIRED/);});
test('lifecycle: Released and Completed require distinct evidence and preserve milestones',()=>{assert.equal(lifecycleTransition('active','PROGRAM_RELEASE',{role:'admin',linked:true,effectiveDate:'2026-01-03'}).allowed,false);assert.equal(lifecycleTransition('active','PROGRAM_RELEASE',{role:'admin',linked:true,effectiveDate:'2026-01-03',releaseVerified:true}).state,'released');assert.equal(lifecycleTransition('released','PROGRAM_COMPLETION',{role:'admin',linked:true,effectiveDate:'2026-01-04'}).allowed,false);assert.equal(lifecycleTransition('released','PROGRAM_COMPLETION',{role:'admin',linked:true,effectiveDate:'2026-01-04',completionVerified:true}).state,'completed');assert.equal(lifecycleTransition('active','PROGRAM_COMPLETION',{role:'admin',linked:true,effectiveDate:'2026-01-04',completionVerified:true}).allowed,false);});
test('Ghat: normalize mobile formats and retain prior release context and payment purpose',()=>{const ps=[payment('a','2026-01-02',{purpose:'Ghat'}),payment('b','2026-01-03',{employeePhone:'+8801700000001'}),payment('c','2026-01-04',{employeePhone:'০১৭০০০০০০০১'})],r=ghatDutyCandidates(ps,{currencyContext:'BDT',priorEvents:[{employee_id:'01700000001',eventType:'PROGRAM_RELEASE',accepted:true,effectiveDate:'2026-01-01',reference:ref('release')}]});assert.equal(r.candidates.length,1);assert.equal(r.candidates[0].priorReleaseVerified,true);assert.deepEqual(r.candidates[0].priorLifecycleReferences,[ref('release')]);assert.equal(r.evidence[0].purpose,'Ghat');assert.equal(r.candidates[0].classification,'HIGH_PRIORITY_GHAT_REVIEW');});
