test('lifecycle: complete release/completion chain requires OCR and a separate source-bound completion decision',()=>{const rel=transitionMessage('release','Program release','2026-01-03','Release Date: 2026-01-03'),complete=transitionMessage('complete','Program completed','2026-01-04'),ocr={mediaSha:'a'.repeat(64),reference:ref('document'),fields:{employee_id:'01700000001',releaseDate:'2026-01-03'}},verification={decision:'APPROVED',approver:'owner',mediaSha:ocr.mediaSha,programId:'p',identityFieldsVerified:true,releaseFieldsVerified:true};const r=life([rel,complete],{knownPrograms:[programContext()],releaseEvidence:{release:{mediaAvailable:true,ocrEvidence:ocr,verification}},transitionEvidence:{complete:transitionProof('complete',{completionDate:'2026-01-04'})}});assert.equal(r.programs[0].state,'completed');assert.equal(r.events.find(e=>e.messageId==='release').stateAfter,'released');assert.equal(r.events.find(e=>e.messageId==='complete').stateBefore,'released');assert.equal(r.programs[0].history.length,2);assert.ok(r.assignments.every(a=>a.open===false));assert.ok(r.events.every(e=>!Object.hasOwn(e,'settlementApproved')));});
