test('lifecycle: conflicting owner role attestations fail closed',()=>{const r=life([message()],{roleBindings:[roleProof(),roleProof('client')]});assert.equal(r.events[0].role,null);assert.equal(r.programs.length,0);assert.equal(r.orders.length,0);});
test('lifecycle: after-five-day repetition of unchanged old duty details cannot create a second program',()=>{const r=life([message('a'),message('b','2026-01-07')]);assert.equal(r.programs.length,1);assert.equal(r.events.find(e=>e.messageId==='b').classification,'REPEATED_BUSINESS_DETAILS_REVIEW');assert.ok(r.events.find(e=>e.messageId==='b').reasons.includes('DISTINCT_BUSINESS_EVENT_EVIDENCE_REQUIRED'));});
test('lifecycle: cancellation mentions/questions remain lexical review even with verified Admin',()=>{const m=message('question','2026-01-02',{body:'Need to cancel the last programme?\nProgram ID: p\nEffective Date: 2026-01-02'}),r=life([m],{knownPrograms:[programContext()]});assert.equal(r.events[0].eventType,'PROGRAM_CANCELLATION');assert.equal(r.events[0].intentEvidence,'LEXICAL_REVIEW_ONLY');assert.equal(r.events[0].accepted,false);assert.equal(r.programs[0].state,'active');assert.ok(r.events[0].reasons.includes('EXPLICIT_TRANSITION_ASSERTION_REQUIRED'));});

test('Ghat: changed content for one payment occurrence rejects rather than discards conflict',()=>assert.throws(()=>ghatDutyCandidates([payment('same','2026-01-01'),payment('same','2026-01-02')],{currencyContext:'BDT'}),/GHAT_SOURCE_OCCURRENCE_CONFLICT/));
test('lifecycle: one message with multiple lighters preserves original occurrence and unique replay binding keys',()=>{const m=message('multi','2026-01-01',{body:message().body+'\n'+message().body.replace('MV Lighter','MV Other Lighter')}),r=life([m,m]);assert.equal(r.programs.length,2);assert.equal(r.events.length,2);assert.equal(new Set(r.events.map(e=>e.sourceOccurrenceId)).size,1);assert.equal(new Set(r.events.map(e=>e.bindingKey.event_key)).size,2);assert.ok(r.events.every(e=>e.bindingKey.occurrence_id===m.reference.occurrenceId));const sql=readFileSync(new URL('../db/migration-candidates/0006_employee_program_identity.sql',import.meta.url),'utf8');assert.match(sql,/FOREIGN KEY \(decision_id,occurrence_id,role,event_key\) REFERENCES ep_review_decisions\(id,occurrence_id,role,event_key\)/);assert.equal((sql.match(/event_key text NOT NULL DEFAULT ''/g)??[]).length,2);});

test('lifecycle: changed body line positions for same source occurrence reject before block splitting',()=>assert.throws(()=>life([message('same'),message('same','2026-01-01',{body:'Extra header\n'+message().body})]),/LIFECYCLE_OCCURRENCE_CONFLICT/));

test('lifecycle: explicitly linked existing incomplete Draft promotes the same anchor and preserves its evidence',()=>{const d=programContext({state:'draft',employee_id:'',startDate:'',shift:'',lighterVessel:'',assignmentId:null}),m=message('confirm','2026-01-02',{body:'Program ID: p\n'+message().body}),r=life([m],{knownPrograms:[d]});assert.equal(r.programs.length,1);assert.equal(r.programs[0].id,'p');assert.equal(r.programs[0].state,'confirmed');assert.equal(r.programs[0].references.length,2);assert.equal(r.events[0].linkedProgramId,'p');assert.equal(r.events[0].stateBefore,'draft');assert.equal(r.programs[0].actualStartDate,null);assert.equal(r.orders.length,0);});
